```
<!-- NAME_1.html -->

<!DOCTYPE html>
<html>
<head>
  <title>JSON Data Table</title>
  <style>
    table {
      border-collapse: collapse;
      border-spacing: 0;
      width: 100%;
    }

    td, th {
      border: 1px solid #ddd;
      padding: 8px;
    }

    th {
      background-color: #f0f0f0;
    }
  </style>
</head>
<body>
  <h1>JSON Data Table</h1>
  <table id="json-table">
    <thead>
      <tr>
        {% for key in data.header %}
        <th>{{ key | markdownify }}</th>
        {% endfor %}
      </tr>
    </thead>
    <tbody>
      {% for row in data.rows %}
      <tr>
        {% for value in row %}
        <td>{{ value | markdownify }}</td>
        {% endfor %}
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <script>
    // Load the JSON data
    fetch('data.json')
      .then(response => response.json())
      .then(data => {
        // Update the table with the JSON data
        const table = document.getElementById('json-table');
        table.innerHTML = '';
        const header = data.header.map(header => `<th>${header}</th>`).join('');
        const rows = data.rows.map(row => row.map(value => `<td>${value}</td>`).join('')).join('');
        table.innerHTML = `<thead><tr>${header}</tr></thead><tbody>${rows}</tbody>`;
      });
  </script>
</body>
</html>
```
