Here is a simple implementation of a red heart made up of fractals in p5.js and WebGL:

```javascript
let inc = 0.1;
let maxIterations = 1000;
let a = 0;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
}

function draw() {
  background(255);

  // Red Heart Fractal
  translate(width/2, height/2);
  rotateY(a);
  rotateX(a);
  noStroke();

  for (let z = 0; z < 1; z += inc) {
    let NovaSize = 50;
    let NovaColor = lerpColor(color(255, 0, 0), color(255, 215, 0), z);
    drawNova(z, NovaSize, NovaColor);
  }

  a += 0.01;
}

function drawNova(z, size, color) {
  for (let j = 0; j < size; j++) {
    beginShape(QUAD_STRIP, 0, 0);
    for (let i = 0; i < size; i++) {
      let trial = z;
      let count = 0;
      for (let t = 0; t < maxIterations; t++) {
        trial = trial*trial + 1 - i;
        if (abs(trial) > 10) {
          count = t;
          break;
        }
      }
      let novaColor = lerpColor(color(255, 0, 0), color(255, 215, 0), count/maxIterations);
      fill(novaColor, 255);
      vertex(i, j, 0);
      vertex(i+1, j, 0);
    }
    endShape();
  }
}
```

This code creates a red heart fractal by calculating the Mandelbrot set at each pixel on the screen. The color of the pixel is then determined by the number of iterations it takes for the Mandelbrot equation to diverge (i.e., the distance to the fractal boundary). The result is a colorful, heart-shaped pattern that can be rotated by adjusting the `a` variable.

