```
using Stripe;
using System;
using System.Web.Http;

namespace StripeExample
{
    public class StripeController : ApiController
    {
        [HttpPost]
        public IHttpActionResult CreateCustomer([FromBody] CreateCustomerRequest request)
        {
            var stripe = new StripeConfiguration(ServiceConstants.StripeApiKey);
            var customerService = new CustomerService(stripe);

            try
            {
                // Create a new customer
                var customer = customerService.Create(new CustomerCreateOptions
                {
                    Email = request.Email,
                    Name = request.Name,
                    Phone = request.Phone,
                    Address = new Address
                    {
                        State = request.AddressState,
                        Country = request.AddressCountry
                    }
                });

                // Create a new payment method (e.g. card)
                var paymentMethodService = new PaymentMethodService(stripe);
                var paymentMethod = paymentMethodService.Create(new PaymentMethodCreateOptions
                {
                    Type = "card",
                    Card = new CardOptions
                    {
                        Number = request.CardNumber,
                        ExpMonth = request.ExpirationMonth,
                        ExpYear = request.ExpirationYear,
                        Cvc = request.CardSecurityCode
                    }
                });

                // Subscribe the customer to a plan with a trial period
                var planService = new PlanService(stripe);
                var plan = planService.Retrieve("your_plan_id");

                var subscriptionService = new SubscriptionService(stripe);
                var subscription = subscriptionService.Create(new SubscriptionCreateOptions
                {
                    Customer = customer.Id,
                    Items = new []
                    {
                        new SubscriptionCreateOptions.SubscriptionItem
                        {
                            Plan = plan.Id,
                            Quantity = 1
                        }
                    },
                    Trial = new SubscriptionCreateOptions.Trial
                    {
                        Days = 30 // 30-day trial period
                    }
                });

                // Return a success response
                return Ok(new { success = true });
            }
            catch (StripeException ex)
            {
                // Return an error response with the Stripe error message
                return BadRequest(new { error = ex.Message });
            }
        }
    }

    public class CreateCustomerRequest
    {
        public string Email { get; set; }
        public string Name { get; set; }
        public string Phone { get; set; }
        public string AddressState { get; set; }
        public string AddressCountry { get; set; }
        public string CardNumber { get; set; }
        public int ExpirationMonth { get; set; }
        public int ExpirationYear { get; set; }
        public string CardSecurityCode { get; set; }
    }
}
```
