        message_queue::remove("MyMessageQueue");
        message_queue mq(open_or_create, "MyMessageQueue", read_write);
        mq.send("Server message", sizeof("Server message") - 1, 0);

        // Acquire file lock 1
        lock1.lock();
        cout << "Server: acquired file lock 1" << endl;
        this_thread::sleep_for(chrono::seconds(1));
        lock1.unlock();

        // Acquire file lock 2
        lock2.lock();
        cout << "Server: acquired file lock 2" << endl;
        this_thread::sleep_for(chrono::seconds(1));
