// Функция для вычисления интеграла методом прямоугольников
double integrateRectangle(std::function<double(double)> f, double a, double b, int n) {
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        result += f(a + i * h);
    }
    return h * result;
}

// Функция для вычисления интеграла методом трапеций
double integrateTrapezoid(std::function<double(double)> f, double a, double b, int n) {
    double h = (b - a) / n;
    double result = 0.5 * (f(a) + f(b));
    for (int i = 1; i < n; i++) {
        result += f(a + i * h);
    }
    return h * result;
}

// Функция для вычисления интеграла методом Симпсона
double integrateSimpson(std::function<double(double)> f, double a, double b, int n) {
    double h = (b - a) / n;
    double result = f(a) + f(b);
    for (int i = 1; i < n; i++) {
        if (i % 2 == 0) {
            result += 2 * f(a + i * h);
        } else {
            result += 4 * f(a + i * h);
        }
    }
    return h / 3 * result;
}

// Функция, которая будет выполняться в отдельных потоках
DWORD WINAPI worker(LPVOID lpParameter) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dis(0, 1);

    double (*f)(double) = (double (*) (double))lpParameter;

    double a = 0;
    double b = 5;
    int n = 100;
    double result = 0;

    for (int i = 0; i < 10000; i++) {
        double x = dis(gen);
        result += f(x);
        Sleep(100); // SMALL DELAY
    }

    HANDLE hMutex = CreateMutex(NULL, FALSE, NULL);
    WaitForSingleObject(hMutex, INFINITE);
    printf("Result: %f\n", result);
    ReleaseMutex(hMutex);

    return 0;
}

int main() {
    HANDLE hMutex = CreateMutex(NULL, FALSE, NULL);
    HANDLE hSem = CreateSemaphore(NULL, 0, 10000, NULL);

    std::function<double(double)> f = [](double x) { return x * x; };

    CREATE_THREAD_ATTRIBUTES attr;
    attr.dwStackSize = 0;
    attr.lpunarithmetic = NULL;
    attr.dwCreationFlags = 0;
    attr.lpfnThreadProc = worker;
    attr.lpParameter = (LPVOID)&f;

    DWORD id;
    HANDLE hThread;

    for (int i = 0; i < 5; i++) {
        CreateThread(NULL, 0, nullptr, &attr, i, &id);
    }

    while (WaitForSingleObject(hSem, 0) == WAIT_TIMEOUT) {
        Sleep(100);
    }

    CloseHandle(hMutex);
    CloseHandle(hSem);
    return 0;
}
