struct Nodo {
    int valor;
    Nodo* izq;
    Nodo* der;
};

Nodo* crearNodo(int valor) {
    Nodo* nuevo = new Nodo();
    nuevo->valor = valor;
    nuevo->izq = nullptr;
    nuevo->der = nullptr;
    return nuevo;
}

Nodo* insertarNodo(Nodo* raiz, int valor) {
    if (raiz == nullptr) {
        return crearNodo(valor);
    }

    if (valor < raiz->valor) {
        raiz->izq = insertarNodo(raiz->izq, valor);
    } else if (valor > raiz->valor) {
        raiz->der = insertarNodo(raiz->der, valor);
    }

    return raiz;
}

Nodo* buscarNodo(Nodo* raiz, int valor) {
    if (raiz == nullptr) {
        return nullptr;
    }

    if (valor == raiz->valor) {
        return raiz;
    }

    if (valor < raiz->valor) {
        return buscarNodo(raiz->izq, valor);
    } else {
        return buscarNodo(raiz->der, valor);
    }
}

int main() {
    Nodo* raiz = nullptr;

    raiz = insertarNodo(raiz, 5);
    insertarNodo(raiz, 2);
    insertarNodo(raiz, 8);
    insertarNodo(raiz, 3);
    insertarNodo(raiz, 9);

    Nodo* nodoEncontrado = buscarNodo(raiz, 8);

    if (nodoEncontrado != nullptr) {
        cout << "Encontrado: " << nodoEncontrado->valor << endl;
    } else {
        cout << "No encontrado" << endl;
    }

    return 0;
}
