      + `&.redirect_uri=${redirectUri}`
      + `&response_type=code`
      + `&scope=${scopes.join(' ')}`;

    window.location.href = authorizationUrl;
  };

  // Handle oauth2 logout button click
  handleLogoutClick = () => {
    this.setState({ token: null, user: null });
  };

  render() {
    const { token, user } = this.state;

    return (
      <div className="container">
        <MenuBar
